 'AGT':'S','AGC':'S','AGA':'R','AGG':'R','GGT':'G','GGC':'G','GGA':'G','GGG':'G',
}

def revcomp(s):
    comp = {'A':'T','T':'A','C':'G','G':'C'}
    return ''.join(comp[c] for c in reversed(s))

# Find ORFs (start to stop) in all 6 frames
def find_orfs(s, frame, minlen=100):
    orfs = []
    i = frame
    start = None
    while i + 3 <= len(s):
        codon = s[i:i+3]
        if codon == 'ATG' and start is None:
            start = i
        if codon in ('TAA','TAG','TGA') and start is not None:
            orfs.append((start, i+3, i+3-start, s[start:i+3]))
            start = None
        i += 3
    # trailing
    if start is not None:
        orfs.append((start, len(s), len(s)-start, s[start:]))
    return orfs

all_orfs = []
for f in range(3):
    for (st,en,ln,sub) in find_orfs(seq, f, 0):
        all_orfs.append((f, '+', st, en, ln))
for f in range(3):
    rc = revcomp(seq)
    for (st,en,ln,sub) in find_orfs(rc, f, 0):
